rubric_json:
{
  "rubrics": [
    {
      "rubric": "Does the analysis calculate the observed 10-year CHD event rate in the operationally eligible population as approximately 19.6% (217/1108) and identify this as higher than the assumed 15% control group rate?",
      "weight": 10,
      "criterion": [
        "The analysis computes the TenYearCHD event rate (proportion of TenYearCHD=1) after applying age 45-70, sysBP 130-159, prevalentStroke=0, and diabetes=0",
        "The computed rate is approximately 19.6% (217 events out of 1,108 subjects)",
        "The analysis explicitly compares this empirical rate to the 15% assumed control rate from the study proposal",
        "The analysis notes the discrepancy of approximately 4.6 percentage points between the empirical and assumed rates"
      ]
    },
    {
      "rubric": "Does the analysis recalculate sample size using the empirically-derived control event rate of approximately 19.6% and demonstrate the impact on required sample size?",
      "weight": 10,
      "criterion": [
        "The analysis provides an alternate sample size calculation using p0≈0.196 based on the observed CHD event rate (217/1,108) in the operationally eligible population",
        "The alternate calculation preserves the same 5-percentage-point absolute risk reduction target, using p1≈0.146 (or a transparently rounded equivalent)",
        "The recalculated sample size differs from the original calculation (using the assumed 15% control rate), demonstrating sensitivity to baseline event rate assumptions"
      ]
    },
    {
      "rubric": "Does Sample_Size_Justification.xlsx contain a complete matrix showing sample sizes across all 8 scenarios (2 power levels × 2 effect sizes × with/without interim adjustment)?",
      "weight": 8,
      "criterion": [
        "The file presents a sensitivity matrix covering two power levels (80% and 90%)",
        "The matrix covers two absolute risk reductions: 3% (p1=0.12) and 5% (p1=0.10)",
        "Both unadjusted and interim-analysis-adjusted calculations are included",
        "There are exactly 8 distinct scenarios, each with computed per-group and total sample sizes"
      ]
    },
    {
      "rubric": "Does Baseline_Subgroup_Analysis.xlsx correctly stratify the eligible population by all four pre-specified subgroups (age groups, gender, baseline risk tertiles, smoking status)?",
      "weight": 10,
      "criterion": [
        "The analysis stratifies the 1,108 operationally eligible subjects by age groups (reasonable categories such as 45-54, 55-64, 65-70 or similar)",
        "The analysis stratifies by gender (male vs female using the 'male' variable)",
        "The analysis stratifies by baseline Framingham Risk Score tertiles (calculated or approximated)",
        "The analysis stratifies by smoking status (using currentSmoker variable)",
        "Each stratum is clearly identified with its sample size"
      ]
    },
    {
      "rubric": "Does the analysis flag subgroups with fewer than 30 subjects as insufficient for meaningful subgroup analysis per FDA E9 guidance?",
      "weight": 10,
      "criterion": [
        "The analysis identifies any subgroup strata with fewer than 30 subjects",
        "Such strata are explicitly flagged as potentially underpowered for meaningful subgroup analysis",
        "The flagging references FDA E9 Section 5.7 principles that pre-specified subgroup analyses require adequate sample sizes to be interpretable"
      ]
    },
    {
      "rubric": "Does the analysis calculate mean and standard deviation of sysBP, totChol, and BMI for each subgroup stratum?",
      "weight": 6,
      "criterion": [
        "For each subgroup stratum (age groups, gender, risk tertiles, smoking status), the analysis computes and reports mean and standard deviation of sysBP (systolic blood pressure)",
        "For each subgroup stratum, the analysis computes and reports mean and standard deviation of totChol (total cholesterol)",
        "For each subgroup stratum, the analysis computes and reports mean and standard deviation of BMI"
      ]
    },
    {
      "rubric": "Does the missing data assessment correctly identify glucose as having the highest missingness rate at approximately 9.3% (103/1108) in the operationally eligible population?",
      "weight": 10,
      "criterion": [
        "The analysis reports the proportion of missing data for each variable in the eligible population",
        "The glucose variable is identified as having the highest missingness rate at approximately 9.3% (103 missing out of 1,108 operationally eligible subjects)",
        "Other variables with notable missingness (education, BPMeds, totChol, BMI) are also reported"
      ]
    },
    {
      "rubric": "Does Eligibility_Analysis.xlsx document the number of subjects excluded by each criterion in a CONSORT-style population flow?",
      "weight": 8,
      "criterion": [
        "The file includes a population flow showing the total Framingham dataset size (4,240 subjects)",
        "The flow shows 2,813 subjects after the age criterion and 1,166 after the sysBP criterion",
        "The flow then applies the observable proposal exclusions in a documented order: prevalentStroke=0 leaves 1,152 subjects and diabetes=0 leaves a final operationally eligible population of 1,108",
        "The flow explicitly notes that chronic kidney disease and broader prior-CVD history cannot be evaluated because the required fields are unavailable",
        "The flow enables verification of the filtering process and assessment of generalizability"
      ]
    }
  ]
}

{
  "rubrics": [
    {
      "rubric": "Does the response interpret the clinical relevance of subgroup interaction results, distinguishing between statistical significance and clinical meaningfulness?",
      "weight": 8,
      "criterion": [
        "The response reports whether the treatment-by-age-group and treatment-by-sex interaction terms are statistically significant (p < 0.05).",
        "Regardless of statistical significance, the response discusses clinical relevance—whether observed differences in treatment effects across subgroups are large enough to be clinically meaningful (e.g., >0.3-0.5% HbA1c difference between subgroups).",
        "The interpretation notes that non-significant interactions support a consistent treatment effect across subgroups, which is desirable from a regulatory perspective."
      ]
    },
    {
      "rubric": "Does the forest plot display subgroup-specific treatment effects with 95% CIs for age group (<65 vs ≥65), sex (Male vs Female), and overall effect, with interaction p-values annotated?",
      "weight": 8,
      "criterion": [
        "A forest plot is generated (as an embedded chart in Excel or a separate figure) showing point estimates and 95% CIs for the treatment effect in each subgroup: age <65, age ≥65, Male, Female, and overall.",
        "The plot includes a vertical reference line at zero (no effect).",
        "Interaction p-values for treatment × age group and treatment × sex are annotated on or near the plot."
      ]
    },
    {
      "rubric": "Does the response compute conditional power using the observed Week 12 interim data and an appropriate formula with all intermediate values shown?",
      "weight": 10,
      "criterion": [
        "Conditional power estimates the probability of achieving a significant result at the final analysis (Week 24) given the interim (Week 12) data.",
        "The calculation uses the observed Week 12 treatment effect, the planned final sample size (480), and the information fraction at interim.",
        "A valid conditional power formula is explicitly stated (e.g., CP = Φ(Z_observed × √(I_final/I_interim) − Z_α/2 × √(I_final/I_interim − 1)), or an equivalent formulation).",
        "All intermediate values (observed Z-statistic, information fraction, critical value) are shown."
      ]
    },
    {
      "rubric": "Does the RWE Comparison sheet contrast medication utilization between the real-world cohort and the trial, reporting real-world metformin use at approximately 19.6%, insulin use at approximately 53.4%, and noting the absence of GLP-1 agent data in the real-world dataset?",
      "weight": 6,
      "criterion": [
          "Real-world medication rates from diabetic_data.csv are reported: metformin use approximately 19.6% (any status other than 'No') and insulin use approximately 53.4%.",
          "Trial baseline medication from DX24_phase3_trial_data.csv is reported: prior_metformin rates are high (~83-84% in both arms), consistent with the trial enrolling patients on stable metformin.",
          "The response explicitly acknowledges that the real-world dataset (1999-2008) predates widespread GLP-1 adoption and does not include GLP-1 agent columns.",
          "A formatted comparison table highlights key differences between clinical trial and real-world populations in medication utilization."
      ]
    },
    {
      "rubric": "Does the audit correctly identify the discrepancy between the protocol-assumed common SD of 1.2% and the observed pooled SD (which is substantially lower), and discuss the implication that the study was effectively overpowered?",
      "weight": 6,
      "criterion": [
        "The discrepancy between the protocol-assumed common SD of 1.2% for HbA1c change and the observed pooled SD (which is substantially lower than 1.2%) is explicitly identified and flagged.",
        "The response explains that a lower observed variability means the study was effectively overpowered for the primary endpoint—the original sample size calculation assumed greater variability than observed, resulting in more statistical power than the planned 90%."
      ]
    },
    {
      "rubric": "Does the RWE Comparison sheet correctly report A1C testing proportions by admission type, showing Emergency admissions at approximately 19.2%, Urgent at approximately 17.3%, and Elective at approximately 10.2%, with an overall rate of approximately 16.7%?",
      "weight": 10,
      "criterion": [
        "Using diabetic_data.csv (101,766 encounters), the proportion of encounters with documented A1C testing (A1Cresult is not missing/NaN) is computed stratified by admission type, with an overall A1C testing rate of approximately 16.7%.",
        "Key admission type rates are reported via IDS_mapping.csv: Emergency (admission_type_id=1) at approximately 19.2%, Urgent (id=2) at approximately 17.3%, and Elective (id=3) at approximately 10.2%.",
        "The finding that elective admissions have a substantially lower A1C testing rate compared to emergency admissions is explicitly noted."
      ]
    },
    {
      "rubric": "Does the response correctly apply LOCF imputation, carrying forward Week 12 values for 30 subjects and baseline for 12 subjects who are missing both Week 12 and Week 24, ensuring all 480 ITT subjects are included?",
      "weight": 10,
      "criterion": [
        "The ITT-LOCF analysis includes all 480 randomized subjects.",
        "For the 42 discontinued subjects missing Week 24 HbA1c, Week 12 data is carried forward for the 30 subjects who have it available.",
        "For the 12 subjects missing both Week 12 and Week 24 data, baseline is carried forward (resulting in zero change).",
        "After LOCF imputation, all 480 subjects have a non-missing HbA1c change value, consistent with the protocol synopsis specifying 'ITT population with LOCF'."
      ]
    }
  ]
}

{
  "rubrics": [
    {
      "rubric": "Does the vendor payment integrity audit correctly identify that CHK-1402 ($1,847.50 to ABC Supplies on 02/09/2024) has no matching AP invoice for that exact amount, and investigate it as a potential partial payment against AP10003 ($4,433.05, status Partial)?",
      "weight": 10,
      "criterion": [
        "The response must flag CHK-1402 ($1,847.50) as a discrepancy because no AP invoice in the Q1 2024 USD subledger matches this exact amount",
        "The response must reference the six ABC Supplies invoices: AP10003 ($4,433.05, Partial), AP10758 ($2,204.28, Paid), AP10362 ($2,005.72, Paid), AP10498 ($597.75, Open), AP10155 ($249.12, Open), AP10260 ($3,084.27, Paid)",
        "The most plausible explanation—a partial payment on AP10003 (status 'Partial'), leaving a remaining balance of approximately $2,585.55 ($4,433.05 − $1,847.50)—must be noted",
        "The response should identify this as a vendor payment integrity exception requiring investigation"
      ]
    },
    {
      "rubric": "Does the vendor audit identify that AP10274 (Fast Travel, $970.98) is marked 'Open' with no PaidDate in the AP subledger, but bank reference EFT-2210 shows the payment cleared on 02/10/2024, constituting an AP status error?",
      "weight": 10,
      "criterion": [
        "The response must identify the status inconsistency for AP10274: the bank statement shows EFT-2210 clearing $970.98 to Fast Travel Services on 02/10/2024",
        "The AP subledger records AP10274 ($970.98, Fast Travel, invoice date 2024-02-10, due 2024-03-11) as 'Open' with no PaidDate, which is an AP subledger data integrity error",
        "The response must state that the status should be corrected to 'Paid' with PaidDate 2024-02-10",
        "This discrepancy must appear in the exceptions log as requiring correction"
      ]
    },
    {
      "rubric": "Does the vendor payment cross-reference correctly match at least 5 of the 6 matchable vendor-related bank withdrawals to their corresponding AP invoices, and flag CHK-1402 ($1,847.50) as unmatched?",
      "weight": 10,
      "criterion": [
        "The response must cross-reference 7 vendor-related bank withdrawals (6 checks + 1 EFT) against the AP subledger",
        "At least 5 of the 6 correct matches must be identified: (1) CHK-1401 $2,204.28 → AP10758 (ABC Supplies, Paid); (2) CHK-1403 $2,005.72 → AP10362 (ABC Supplies, Paid); (3) CHK-1404 $3,133.53 → AP10452 (Global Office, Paid); (4) CHK-1405 $2,302.71 → AP10108 (BluePrints, Paid); (5) CHK-1406 $4,543.11 → AP10581 (Global Office, Paid); (6) EFT-2210 $970.98 → AP10274 (Fast Travel, status discrepancy)",
        "CHK-1402 ($1,847.50) must be flagged as having no matching AP invoice"
      ]
    },
    {
      "rubric": "Does the AP aging schedule correctly classify the open/partial Q1 2024 USD invoices into aging buckets as of March 31, 2024, with AP10003 ($4,433.05), AP10454 ($1,074.85), and AP10234 ($2,206.77) in the 31-60 days past due bucket?",
      "weight": 10,
      "criterion": [
        "The response must age all 6 Q1 2024 USD invoices with Open or Partial status as of March 31, 2024",
        "When aging from due date: AP10003 (due 2024-02-07, 53 days past due → 31-60 days), AP10454 (due 2024-02-10, 50 days past due → 31-60 days), AP10234 (due 2024-02-23, 37 days past due → 31-60 days) must be in the 31-60 day bucket",
        "The remaining invoices—AP10498 (due 2024-03-06, 25 days), AP10155 (due 2024-03-24, 7 days), and AP10485 (due 2024-03-25, 6 days)—should fall in the Current/0-30 days bucket",
        "If aging from invoice date instead (yielding 61-90 day bucket for the three oldest), that is acceptable if consistently applied, but the three oldest invoices must be classified in a more aged bucket than the newer ones"
      ]
    },
    {
      "rubric": "Does the Schedule C expense mapping correctly assign COGS (Account 5000, $4,421.20) to Line 4, Travel Expense (Account 5010, $7,534.42) to Line 24a, and Payroll Expense (Account 6000) to Line 26?",
      "weight": 8,
      "criterion": [
        "Account 5000 COGS totaling $4,421.20 (7 entries: $383.71 + $254.62 + $822.42 + $242.28 + $726.03 + $1,835.61 + $156.53) must map to Schedule C Line 4 (Cost of goods sold)",
        "Account 5010 Travel Expense totaling $7,534.42 (8 entries: $283.45 + $200.91 + $753.12 + $292.84 + $1,330.42 + $1,450.58 + $1,814.27 + $1,408.83) must map to Schedule C Line 24a (Travel)",
        "Account 6000 Payroll Expense must map to Schedule C Line 26 (Wages/less employment credits); the GL-only total is $5,861.39 (8 entries), though the response may reconcile this against the $51,000 in bank payroll disbursements",
        "The amounts and line assignments must all be correct"
      ]
    },
    {
      "rubric": "Does the reconciliation identify the significant discrepancy between bank payroll disbursements ($51,000.00 for six payments of $8,500 each) and the GL Payroll Expense account entries ($5,861.39 total from eight smaller entries), and investigate or explain this $45,138.61 gap?",
      "weight": 8,
      "criterion": [
        "The bank statement shows six payroll direct deposits of $8,500.00 each (ACH-PR0115, PR0131, PR0215, PR0229, PR0315, PR0331) totaling $51,000.00, while the GL Account 6000 Payroll Expense contains eight entries totaling only $5,861.39",
        "The response must identify the $45,138.61 discrepancy between bank payroll disbursements and GL payroll expense entries",
        "The response must investigate possible explanations: (a) GL entries are supplemental payroll costs (taxes, benefits, adjustments) while $51,000 cash disbursements were recorded elsewhere or not at all; (b) payroll was accrued to a liability account; (c) systemic failure to record payroll cash transactions in the GL",
        "This is the largest single discrepancy in the reconciliation and must be prominently flagged"
      ]
    },
    {
      "rubric": "Does the reconciliation investigate DEP-0129 ($4,127.26, described as 'Customer Payment net of fees' on 01/29/2024) and analyze the fee deduction by comparing it to the closest GL revenue entry or other deposits?",
      "weight": 6,
      "criterion": [
        "The response must investigate DEP-0129 ($4,127.26) which is described as 'net of fees'",
        "The analysis should compare this to nearby GL entries to determine the gross amount and fee deducted, such as GL000434 ($4,172.26 on 01/29, Account 4000) yielding a fee of $45.00, or GL001447 ($4,741.00 on 01/26, Account 4000) yielding a fee of $613.74",
        "The response must note the ambiguity and explain that the fee should be recorded as an expense (e.g., Account 5020 Bank Service Charges or a payment processing fee account)",
        "Simply ignoring the 'net of fees' notation or failing to investigate the implied fee deduction fails this criterion"
      ]
    },
    {
      "rubric": "Does the reconciliation note the date discrepancy between CHK-1401 (bank clearance date 01/10/2024) and AP10758 (PaidDate listed as 02/09/2024) for the $2,204.28 payment to ABC Supplies?",
      "weight": 10,
      "criterion": [
        "The response must identify that CHK-1401 for $2,204.28 to ABC Supplies cleared the bank on 01/10/2024, but the matching AP record AP10758 lists a PaidDate of 2024-02-09—a 30-day discrepancy",
        "The response should investigate possible causes: the check may have been issued earlier than the bank clearance date, the AP PaidDate may reflect when internal books were updated rather than bank processing, or there may be a data entry error",
        "This discrepancy should appear in the exceptions log"
      ]
    },
    {
      "rubric": "Does the exceptions log (Deliverable 3) contain at least 8 distinct discrepancies with proper Exception_ID, Source_File, Reference, Description, Amount, Resolution, and Status fields?",
      "weight": 6,
      "criterion": [
        "The Q1_2024_Reconciliation_Exceptions.csv must contain at least 8 distinct exceptions covering major discrepancies: (1) CHK-1402 unmatched payment ($1,847.50); (2) AP10274/EFT-2210 status discrepancy ($970.98); (3) CHK-1401/AP10758 date mismatch ($2,204.28); (4) DEP-0129 net-of-fees ambiguity ($4,127.26); (5) NSF returned check ($750.00); (6) Missing GL entries for rent ($9,600); (7) Missing GL entries for auto loan payments ($3,750); (8) Payroll GL vs. bank discrepancy ($45,138.61 gap)",
        "Each exception must have all required columns: Exception_ID (unique identifier), Source_File (which file the discrepancy was found in), Reference (transaction reference number), Description (clear explanation), Amount (dollar amount), Resolution (action taken or recommended), and Status (Resolved or Unresolved)"
      ]
    },
    {
      "rubric": "Does the Schedule C Draft worksheet (Sheet 4 of the Reconciliation Workbook) correctly replicate the Schedule C structure with Part I (Income) including Line 1 gross receipts of $40,557.62 and Part II (Expenses) with line-level amounts that tie back to the expense summary?",
      "weight": 10,
      "criterion": [
        "Sheet 4 must replicate the IRS Schedule C structure with Part I Income showing Line 1 Gross receipts (combined Sales Revenue $23,318.47 + Online Sales $17,239.15 = $40,557.62), Line 4 COGS ($4,421.20), Line 5 Gross Profit ($36,136.42), Line 6 Other income (Interest Income $37.56), and Line 7 Gross income ($36,173.98)",
        "Part II Expenses must include amounts for Line 15 (Insurance), Line 20b (Rent $9,600.00), Line 24a (Travel $7,534.42), Line 25 (Utilities $1,275.00), Line 26 (Wages), and Line 27a (Other expenses—bank charges $105.00)",
        "The amounts must be internally consistent and tie back to the Q1_2024_Schedule_C_Expense_Summary.csv"
      ]
    }
  ]
}

{
  "rubrics": [
    {
      "rubric": "Does the reconciliation correctly identify outstanding checks — cash book checks that have not cleared the bank statement by December 31, 2024?",
      "weight": 6,
      "criterion": [
        "Only checks #1086 ($485.00 on 12/11), #1087 ($1,250.00 on 12/28), #1088 ($1,800.00 on 12/16), and #1089 ($780.00 on 12/23) appear as cleared checks on the bank statement.",
        "All other numbered checks from the cash book (e.g., checks to Ewing Irrigation, Metro Industrial Properties, Jiffy Lube, Arbortech Tree Service, Belgard Hardscapes, State Farm Insurance, and others) must be identified as outstanding checks.",
        "The outstanding checks must be listed with their individual amounts.",
        "Outstanding checks must be shown as items that reduce the bank-side adjusted balance."
      ]
    },
    {
      "rubric": "Does the response correctly identify the Premier Landscape Supply partial payment discrepancy — invoice INV-2024-0412 for $1,520.00 versus the bank check #1087 payment of $1,250.00, and the cash book recording check #1087 as a $350.00 payment to Google LLC for Google Ads?",
      "weight": 6,
      "criterion": [
        "The response must identify the three-way conflict on check #1087: the vendor invoice INV-2024-0412 from Premier Landscape Supply is for $1,520.00, the bank statement shows check #1087 cleared for $1,250.00 to Premier Landscape Supply, and the cash book records check #1087 as $350.00 to Google LLC for Google Ads under Advertising.",
        "The response must identify that the cash book has the wrong payee, wrong amount, and wrong category for check #1087.",
        "The response must note that $270.00 remains unpaid on the invoice ($1,520 − $1,250) and should be carried as accounts payable.",
        "The response must address that the November AP aging showed Premier Landscape Supply with a prior balance of $890.00 (INV-2024-0389), which must also be accounted for."
      ]
    },
    {
      "rubric": "Does the response correctly identify the check #1086 discrepancy — the cash book records $1,287.50 to Al's Auto & Truck Repair, but the bank statement shows $485.00 to Mike's Auto Repair, confirmed by vendor invoice INV-2024-0408?",
      "weight": 6,
      "criterion": [
        "The response must identify the discrepancy: the cash book lists check #1086 on 12/21/2024 as $1,287.50 to Al's Auto & Truck Repair for truck transmission repair, while the bank statement shows check #1086 cleared on 12/11/2024 for $485.00 to Mike's Auto Repair, confirmed by vendor invoice INV-2024-0408.",
        "The response must identify the cash book has the wrong payee, wrong amount, and wrong date for check #1086.",
        "The response must calculate the book error as $802.50 ($1,287.50 − $485.00).",
        "The response must prepare an adjusting journal entry: debit Cash $802.50, credit Repairs and Maintenance $802.50."
      ]
    },
    {
      "rubric": "Does the response correctly identify the two unpaid December vendor invoices (Ace Hardware INV-2024-0435 for $215.00 and Elite Tree Service INV-2024-0438 for $1,100.00) as year-end accrued liabilities totaling $1,315.00?",
      "weight": 6,
      "criterion": [
        "The response must identify INV-2024-0435 from Ace Hardware for $215.00 (dated 12/28/2024, due 01/28/2025, for miscellaneous hardware) as an unpaid December expense requiring accrual: debit Supplies $215.00, credit Accounts Payable $215.00.",
        "The response must identify INV-2024-0438 from Elite Tree Service for $1,100.00 (dated 12/30/2024, due 01/30/2025, for emergency storm damage tree removal) as an unpaid December expense requiring accrual: debit Contract Labor $1,100.00, credit Accounts Payable $1,100.00.",
        "Total accrued liabilities must be stated as $1,315.00.",
        "Both items must be flagged for the accountant preparing the Schedule C return."
      ]
    },
    {
      "rubric": "Does the Schedule C Summary sheet correctly map expense categories to IRS Schedule C line numbers: Line 1 (Gross receipts), Line 8 (Advertising), Line 9 (Car and truck expenses), Line 11 (Contract labor), Line 15 (Insurance), Line 17 (Legal and professional services), Line 18 (Office expense), Line 20b (Rent/lease other business property), Line 21 (Repairs and maintenance), Line 22 (Supplies), Line 23 (Taxes and licenses), Line 25 (Utilities), Line 26 (Wages), and Line 27a (Other expenses)?",
      "weight": 6,
      "criterion": [
        "The Schedule C Summary must map corrected (post-adjustment) expense figures to IRS Schedule C (Form 1040) 2024 line items.",
        "Required line mappings: Line 1 = Gross receipts/revenue, Line 8 = Advertising, Line 9 = Car and truck expenses, Line 11 = Contract labor, Line 15 = Insurance, Line 17 = Legal and professional services, Line 18 = Office expense, Line 20b = Rent/lease other business property, Line 21 = Repairs and maintenance, Line 22 = Supplies, Line 23 = Taxes and licenses, Line 25 = Utilities, Line 26 = Wages, Line 27a = Other expenses.",
        "These line numbers must match the provided IRS Schedule C form.",
        "Actual amounts must reflect post-reconciliation corrected figures, not raw cash book totals."
      ]
    },
    {
      "rubric": "Does the response prepare adjusting journal entries in proper double-entry format (debits equal credits) using correct account names from the chart of accounts?",
      "weight": 10,
      "criterion": [
        "Each adjusting journal entry must include: Date, Account Debited, Account Credited, Amount, and Memo, with debits equaling credits in each entry.",
        "Account names must reference the provided chart of accounts (e.g., 'Bank checking account', 'Accounts payable', 'Bank fees', 'Interest income').",
        "Required entries include: correction of check #1086 error (debit Cash $802.50, credit Repairs & Maintenance $802.50), wire transfer fee (debit Bank Fees $25.00, credit Cash $25.00), and monthly service charge (debit Bank Fees $15.00, credit Cash $15.00).",
        "Required entries also include: interest earned (debit Cash $3.21, credit Interest Income $3.21), Ace Hardware accrual (debit Supplies $215.00, credit Accounts Payable $215.00), and Elite Tree Service accrual (debit Contract Labor $1,100.00, credit Accounts Payable $1,100.00)."
      ]
    },
    {
      "rubric": "Does the response correctly identify that the cash book and bank statement record fundamentally different sets of transactions, and systematically reconcile between the two?",
      "weight": 6,
      "criterion": [
        "The response must recognize that the cash book records checks to vendors such as Ewing Irrigation, Metro Industrial Properties, Jiffy Lube, Arbortech Tree Service, Belgard Hardscapes, Small Engine Repair Co., Sarah Mitchell CPA, and others that do not appear on the bank statement.",
        "The response must recognize that the bank statement records debit card and ACH payments to Shell Oil, Lowe's, Amazon, Facebook Ads, Daily Herald, NAPA Auto Parts, AT&T, Staples, and others not in the cash book.",
        "Checks #1086, #1087, #1088, and #1089 appear on both, but with different payees and/or amounts, and these discrepancies must be addressed.",
        "The reconciliation must systematically account for items on the bank not in the book (requiring book adjustments) and items in the book not on the bank (outstanding items)."
      ]
    },
    {
      "rubric": "Does the management memo state the adjusted true cash balance and report the total count of reconciling items, consistent with the reconciliation worksheet?",
      "weight": 6,
      "criterion": [
        "The variance memo must include the adjusted true cash balance — the single figure that both the adjusted bank balance and adjusted book balance reconcile to.",
        "The memo must report the count of reconciling items identified.",
        "The memo must distinguish between bank-side reconciling items (outstanding checks, deposits in transit, duplicate charges) and book-side reconciling items (unrecorded bank charges, book errors, omissions).",
        "The stated true cash balance must match the Reconciliation sheet of December_2024_Month_End_Close.xlsx."
      ]
    }
  ]
}

{
  "rubrics": [
    {
      "rubric": "Does the estimate calculate the structure excavation volume using a parallelogram footprint rather than assuming a rectangular excavation?",
      "weight": 6,
      "criterion": [
        "The excavation must be calculated using a parallelogram footprint, not a rectangular one.",
        "The parallelogram dimensions must incorporate the skew-adjusted length of approximately 74.5 ft and the appropriate width dimensions.",
        "The calculation must use the perpendicular height method for computing the parallelogram area, demonstrating the geometric effect of the 15-degree skew."
      ]
    },
    {
      "rubric": "Does the reinforcement verification correctly calculate WW-1 total weight as 816 ft × 1.043 lb/ft = 851.09 lb and WW-2 total weight as 882 ft × 1.043 lb/ft ≈ 919.93 lb (919.926 lb before rounding)?",
